Item.method_code:
const selectedIds = window.grid.getSelectedItemIds();
if (!selectedIds.length) {
	return;
}

const { commandFactory, itemType, polySources } = options;
const itemTypeMetadata = ArasModules.metadata.itemType;
const isPolymorphic = itemTypeMetadata.isPolymorphic(itemType.id);
const getItemType = (item) => {
	if (isPolymorphic) {
		const itemTypeId = item.itemtype;
		const itemTypeName = itemTypeMetadata.getItemTypeName(itemTypeId);
		return polySources[itemTypeName];
	}

	return itemType;
};

const rows = window.grid._grid.rows;
const commandAlias = target['command_alias@keyed_name'];
const isSaveEnabled = selectedIds.every((selectedId) => {
	const item = rows.get(selectedId);
	const itemType = getItemType(item);
	const itemTypeName = itemType.name;
	const saveCommand = commandFactory(commandAlias, {
		item,
		itemType,
		itemTypeName
	});

	return saveCommand.canExecute();
});

if (isSaveEnabled && window.onSaveCommand) {
	window.onSaveCommand();
}
